// The IR as CSS keyframes, for the animated SVG and the CSS snippet. See docs/ARCHITECTURE.md section 5.
// Every selector and keyframe name carries the scope, because inline SVG styles are global to the page.
// Uses the DOM only when called, never at import.
import { num } from '../ir/format';
import { fnv1a } from '../parse/hash';
import { sanitise } from '../parse/sanitise';
import { WRAPPER_PROPERTIES, type IR, type Keyframe, type Track } from '../ir/types';

const SVG_NS = 'http://www.w3.org/2000/svg';

// Keys are ours (rewrite.ts). Values and easings are generated by compile from numbers.
// The spec behind them comes from storage, so anything else is refused rather than escaped.
const KEY = /^k[0-9a-f]+$/;
const VALUE = /^[\w\s.,()%-]*$/;
const FUNCTIONS = new Set(['translate(', 'rotate(', 'scale(', 'cubic-bezier(', 'steps(']);

/** Scopes one export: the same file with a different animation never shares names. */
export const scopeOf = (svg: string, ir: IR): string => `s${fnv1a(svg + JSON.stringify(ir.tracks) + ir.duration + ir.iterations)}`;

/** Transform and opacity move the wrapper. Paint and dashes go on the element (invariant 3). */
export function selector(scope: string, track: Pick<Track, 'target' | 'property'>): string {
  if (!KEY.test(track.target)) throw new Error(`Unexpected key: ${track.target}`);
  const attr = WRAPPER_PROPERTIES.has(track.property) ? 'data-for' : 'data-k';
  return `[data-asg="${scope}"] [${attr}="${track.target}"]`;
}

export function checkValue(value: string): string {
  const known = (value.match(/[\w-]+\(/g) ?? []).every((fn) => FUNCTIONS.has(fn));
  if (!VALUE.test(value) || !known) throw new Error(`Unexpected value: ${value}`);
  return value;
}

/** Percentages, four decimals. Two keyframes at one offset are a jump, but CSS merges equal percentages. */
function percentages(keyframes: Keyframe[]): number[] {
  const out = keyframes.map(({ offset }) => Math.round(offset * 1e6) / 1e4);
  for (let i = 1; i < out.length; i++) {
    if (out[i] !== out[i - 1]) continue;
    // Pull the earlier one back, so at the exact moment CSS shows the later value, as WAAPI does.
    if (out[i] > 0) out[i - 1] = Math.round((out[i] - 0.001) * 1e4) / 1e4;
    else out[i] = 0.001;
  }
  return out;
}

function keyframesRule(name: string, track: Track): string {
  const at = percentages(track.keyframes);
  const frames = track.keyframes.map(({ value, easing }, i) => {
    const timing = easing === 'linear' ? '' : `;animation-timing-function:${checkValue(easing)}`;
    return `${at[i]}%{${track.property}:${checkValue(value)}${timing}}`;
  });
  return `@keyframes ${name}{${frames.join('')}}`;
}

/** Keyframes for every track, and the rules that play them, inside a reduced-motion guard. */
export function css(ir: IR, scope: string): string {
  const keyframes: string[] = [];
  const animations = new Map<string, string[]>();
  const count = ir.iterations === 'infinite' ? 'infinite' : '1';
  ir.tracks.forEach((track, i) => {
    const name = `${scope}-${i}`;
    keyframes.push(keyframesRule(name, track));
    const rule = selector(scope, track);
    const list = animations.get(rule) ?? animations.set(rule, []).get(rule)!;
    list.push(`${name} ${ir.duration}s linear ${count} both`);
  });
  const rules = [...animations].map(([rule, list]) => `${rule}{animation:${list.join(',')}}`);
  // With reduced motion nothing plays, and the drawing shows as it was authored.
  return `${keyframes.join('\n')}\n@media (prefers-reduced-motion:no-preference){\n${rules.join('\n')}\n}`;
}

/**
 * The normalised file as an export: scoped, given a natural size, with `style` inside if given,
 * then checked by the export sanitiser. Fails rather than ship anything the check changed.
 */
export function exportMarkup(svg: string, scope: string, style?: string): string {
  const doc = new DOMParser().parseFromString(svg, 'image/svg+xml');
  const root = doc.documentElement;
  root.setAttribute('data-asg', scope);
  // Normalise removed the authored size. The viewBox gives the file one, so it does not shrink to 300 x 150 in <img>.
  const [, , width, height] = (root.getAttribute('viewBox') ?? '').trim().split(/[\s,]+/).map(Number);
  if (width > 0 && height > 0) {
    root.setAttribute('width', num(width));
    root.setAttribute('height', num(height));
  }
  if (style) {
    const element = doc.createElementNS(SVG_NS, 'style');
    element.textContent = style;
    root.prepend(element);
  }
  const checked = sanitise(new XMLSerializer().serializeToString(root), 'export').root;
  if (style && checked.querySelector('style')?.textContent !== style) throw new Error('Export refused: the check changed the animation.');
  return new XMLSerializer().serializeToString(checked);
}

/** The animated SVG download: keyframes inside the file. Works inline and in <img>. */
export function animatedSvg(svg: string, ir: IR): string {
  const scope = scopeOf(svg, ir);
  return exportMarkup(svg, scope, css(ir, scope));
}
